import {Simulation,MISSIONS,distance,angleTo,clamp} from './simulation.js';
import {OceanScene} from './scene.js';
const icons={sonar:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><path d="M12 12 18 6M12 2v2M2 12h2M20 12h2M12 20v2"/>',sub:'<path d="M4 11h14a4 4 0 0 1 0 8H4a4 4 0 0 1 0-8Z M9 11V7h6v4M12 7V3h3M21 14h2M21 17h2"/>',target:'<circle cx="12" cy="12" r="7"/><path d="M12 1v6M12 17v6M1 12h6M17 12h6"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2ZM9 3v16M15 5v16"/>',wave:'<path d="M2 12h4l2-7 4 14 4-14 2 7h4"/>',shield:'<path d="m12 3 8 3v7c0 5-8 8-8 8s-8-3-8-8V6ZM8 12l3 3 5-6"/>',torpedo:'<path d="m6 18 9-13 4-1 1 4-13 9-4 4 1-5Z M12 8l4 4"/>',sound:'<path d="m11 4-6 5H2v6h3l6 5ZM15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 8a3 3 0 0 1 6 0c0 3-3 2-3 5M12 16v1"/>',chevron:'<path d="m9 5 7 7-7 7"/>',pause:'<path d="M8 5v14M16 5v14"/>',play:'<path d="m7 4 13 8-13 8Z"/>',save:'<path d="M4 3h13l4 4v14H3V3ZM7 3v6h10V3M7 21v-8h10v8"/>',battery:'<rect x="2" y="6" width="18" height="12" rx="2"/><path d="M22 10v4M6 10v4M10 10v4M14 10v4"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5Z"/>',depth:'<path d="M12 3v18M7 16l5 5 5-5M5 4h14M5 8h3M16 8h3"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.sonar}</svg>`;
const $=s=>document.querySelector(s);let sim=new Simulation();let view='chase',soundOn=false,ctx,master,ambient,resultShown=false,logsOpen=false;let displayTime=0;let seenLogs=-1;let radarRange=600;let toastTimer;let scene;
const observed=e=>e.lastContact||e;
const fmt=n=>String(Math.floor(n)).padStart(2,'0');const clock=n=>`${fmt(n/60)}:${fmt(n%60)}`;
$('#app').innerHTML=`
<header class="topbar"><a class="brand" href="./" aria-label="深海静默首页"><span class="brand-mark">${icon('sonar')}</span><span>深海静默<small>ABYSS COMMAND</small></span></a><nav class="view-nav" aria-label="作战视图"><button class="active" data-view="chase">${icon('sub')}三维战场</button><button data-view="sonar">${icon('wave')}声呐室</button><button data-view="map">${icon('map')}战术海图</button></nav><div class="header-actions"><span class="connection"><i></i>舰载系统在线</span><button id="sound" class="icon-btn" aria-label="开启声音" title="开启声音">${icon('sound')}</button><button id="help" class="icon-btn" aria-label="操作指南" title="操作指南">${icon('help')}</button></div></header>
<div class="operation-bar"><div><span class="overline" id="operation-number">OPERATION 01</span><h1 id="mission-name">无声猎手</h1><span class="divider"></span><span id="sector">北大西洋 · 挪威海盆</span></div><div><span class="weather">海况 3 级<span> / </span>温跃层 180 m</span><button id="missions" class="text-btn">切换任务 ${icon('chevron')}</button></div></div>
<main class="command-grid">
<aside class="left-stack"><section class="panel mission-panel"><div class="panel-title"><span>任务简报</span><span class="tag">机密 / SECRET</span></div><p id="mission-desc"></p><div class="objective-list" id="objectives"></div><div class="mission-time"><span>任务剩余</span><strong id="remaining">12:00</strong></div><div class="mission-progress"><i id="mission-progress"></i></div><button id="start" class="primary-btn">${icon('play')} 启动巡航 <kbd>Enter</kbd></button><button id="load" class="text-btn load-btn">继续本机存档</button></section>
<section class="panel contacts-panel"><div class="panel-title"><span>声呐接触</span><span class="count" id="contact-count">02</span></div><div id="contacts"></div><div class="listen-status"><span class="listen-bars"><i></i><i></i><i></i><i></i><i></i></span> 被动监听持续运行</div></section>
<section class="panel log-panel"><div class="panel-title"><span>航行日志</span><button id="logs" class="tiny-btn">全部记录</button></div><div id="log-list" aria-live="polite"></div></section></aside>
<section class="center-stack"><div class="viewport panel" id="viewport"><div id="ocean"></div><canvas id="tactical" aria-label="战术海图，点击设置航向"></canvas><div class="viewport-grain"></div><div class="viewport-top"><span><i class="live-dot"></i><b id="view-label">外部观察</b> <span class="subdued">/ SSN-774</span></span><div class="camera-modes"><button class="active" data-camera="chase" title="跟随镜头">跟随</button><button data-camera="periscope" title="潜深小于 45 米时可使用">潜望镜</button></div></div><div class="compass-ribbon" id="compass-ribbon"></div><div class="viewport-coordinates"><span>68° 24′ N</span><span>02° 16′ E</span><i></i><span>挪威海盆 / C-07</span></div><div class="depth-ruler"><span>050</span><span>100</span><span class="current-depth" id="ruler-depth">120</span><span>150</span><span class="thermal-marker">180 — 温跃层</span><span>250</span></div><div class="ship-caption"><span>SSN-774</span><h2>「幽灵」号</h2><div>弗吉尼亚级 · 攻击型核潜艇</div></div><div class="center-reticle"><i></i><i></i><i></i><i></i></div><div class="viewport-bottom"><span id="camera-help">拖动旋转视角 · 滚轮缩放</span><span><i class="live-dot"></i><span id="depth-status">温跃层上方</span></span></div><div id="viewport-alert" class="viewport-alert"></div><div id="pause-overlay" class="pause-overlay" hidden><div>${icon('pause')}<h2>战术暂停</h2><p>航行与敌方行动已冻结</p><button id="resume" class="primary-btn">继续航行</button></div></div></div>
<section class="panel helm"><div class="panel-title"><span>${icon('compass')} 航行控制</span><span class="subdued">HELM CONTROL</span></div><div class="helm-grid"><div class="helm-control"><div class="control-name"><span>航速</span><kbd>W / S</kbd></div><div class="value"><strong id="speed-value">5.0</strong><span>节</span><small id="speed-order">指令 5</small></div><input id="speed" aria-label="目标航速" type="range" min="0" max="25" value="5"><div class="range-labels"><span>停车</span><span>巡航</span><span>全速</span></div></div><div class="helm-control"><div class="control-name"><span>航向</span><kbd>A / D</kbd></div><div class="value"><strong id="heading-value">000</strong><span>°</span><small id="heading-order">正北</small></div><input id="heading" aria-label="目标航向" type="range" min="0" max="359" value="0"><div class="range-labels"><span>N</span><span>E</span><span>S</span><span>W</span><span>N</span></div></div><div class="helm-control"><div class="control-name"><span>潜深</span><kbd>Q / E</kbd></div><div class="value"><strong id="depth-value">120</strong><span>米</span><small id="depth-order">指令 120</small></div><input id="depth" aria-label="目标潜深" type="range" min="35" max="380" value="120"><div class="range-labels"><span>浅水</span><span class="mint">180 m</span><span>深潜</span></div></div></div><button id="silent" class="silent-toggle">${icon('shield')}<span>静默航行<small>降低机械噪声 · 航速限制 5 节</small></span><kbd>C</kbd><span class="toggle"></span></button></section>
</section>
<aside class="right-stack"><section class="panel sonar-panel"><div class="panel-title"><span>${icon('sonar')} 战术声呐</span><button id="range" class="tiny-btn">6 km</button></div><div class="radar-wrap"><canvas id="radar" aria-label="声呐接触雷达，点击接触选择目标"></canvas><span class="radar-n">N</span><span class="radar-e">E</span><span class="radar-s">S</span><span class="radar-w">W</span></div><div class="sonar-legend"><span><i class="mint-dot"></i>本艇</span><span><i class="contact-dot"></i>接触</span><span><i class="danger-dot"></i>威胁</span></div><button id="ping" class="scan-btn">${icon('sonar')}<span id="ping-label">主动声呐脉冲</span><kbd>Space</kbd></button><p class="warning-note">主动发声可能暴露你的位置</p></section>
<section class="panel signature-panel"><div class="panel-title"><span>隐蔽状态</span><span id="stealth-label" class="mint">隐蔽</span></div><div class="metric-row"><span>辐射噪声</span><strong><span id="noise-value">23</span> <small>dB</small></strong></div><div class="segmented-meter" id="noise-meter"></div><div class="metric-row"><span>敌方锁定</span><strong id="exposure-value">0%</strong></div><div class="thin-progress"><i id="exposure-meter"></i></div><div class="thermal-info" id="thermal-info">${icon('depth')}下潜至 180 m 以下可利用温跃层隐蔽</div></section>
<section class="panel weapon-panel"><div class="panel-title"><span>${icon('target')} 武器控制</span><span id="ammo-count" class="tag">08 枚</span></div><div id="target-info" class="target-info">选择声呐接触以建立射击解算</div><div class="solution-row"><span>射击解算</span><strong id="solution-value">—</strong></div><div class="thin-progress"><i id="solution-meter"></i></div><button id="fire" class="fire-btn">${icon('torpedo')}<span id="fire-label">发射鱼雷</span><kbd>F</kbd></button><button id="decoy" class="decoy-btn">${icon('wave')}<span id="decoy-label">释放声学诱饵</span><span id="decoy-count">4</span><kbd>G</kbd></button></section></aside>
</main><footer class="status-bar"><div class="vessel-status"><span>${icon('shield')}艇体 <b id="hull">100%</b><i class="mini-meter"><i id="hull-bar"></i></i></span><span>${icon('battery')}电量 <b id="battery">100%</b></span><span><span class="oxygen-icon">O₂</span>氧气 <b id="oxygen">100%</b></span><button id="repair" class="text-btn">紧急损管</button></div><div class="footer-right"><button id="save" class="icon-btn" title="保存本机进度" aria-label="保存本机进度">${icon('save')}</button><button id="time-scale" class="time-scale">1×</button><button id="pause" class="icon-btn" aria-label="暂停航行" title="暂停 P">${icon('pause')}</button><span id="game-time">T+ 00:00</span><span class="status-label" id="game-state">待命</span></div></footer><div id="toast" role="status" class="toast"></div><dialog id="modal"></dialog>`;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
function tone(freq=440,duration=.3,type='sine',volume=.12){if(!soundOn)return;try{ctx??=new(window.AudioContext||window.webkitAudioContext)();ctx.resume();const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(50,freq*.7),ctx.currentTime+duration);g.gain.setValueAtTime(volume,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+duration);o.connect(g).connect(ctx.destination);o.start();o.stop(ctx.currentTime+duration)}catch{}}
function eventSound(e){if(e.type==='ping')tone(900,1.8,'sine',.17);if(e.type==='launch')tone(150,.6,'sawtooth',.05);if(e.type==='explosion')tone(75,.6,'triangle',.2);if(e.type==='alarm'){tone(660,.2);setTimeout(()=>tone(520,.2),250)}}
function perform(method){const result=sim[method]();if(result?.ok===false)toast(result.reason);syncControls();updateUI(true)}
function start(){sim.start();syncControls();updateUI(true);tone(340,.2)}
function syncControls(){$('#speed').value=sim.player.desiredSpeed;$('#depth').value=sim.player.desiredDepth;$('#heading').value=Math.round(sim.player.desiredHeading);$('#speed').max=sim.player.silent?5:25;$('#silent').classList.toggle('enabled',sim.player.silent)}
function setView(next){view=next;document.querySelectorAll('[data-camera]').forEach(b=>b.classList.toggle('active',b.dataset.camera===next));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===(next==='periscope'?'chase':next)));const isMap=next==='map'||next==='sonar';$('#tactical').style.display=isMap?'block':'none';$('#ocean').style.visibility=isMap?'hidden':'visible';$('#viewport').classList.toggle('map-mode',isMap);$('#view-label').textContent=next==='sonar'?'宽域声呐分析':next==='map'?'战术海图':next==='periscope'?'潜望镜观察':'外部观察';$('#camera-help').textContent=next==='map'?'点击海图设定航向 · 点击接触锁定目标':next==='sonar'?'被动监听 · 点击接触分析信号':'拖动旋转视角 · 滚轮缩放';scene?.setMode(next==='periscope'?'periscope':'chase')}
function save(){try{localStorage.setItem('abyss-save-v1',sim.save());toast('航行进度已保存到此设备')}catch{toast('无法保存：浏览器存储不可用')}}
function load(){try{const raw=localStorage.getItem('abyss-save-v1');if(!raw)return toast('此设备暂无存档');sim=Simulation.restore(raw);resultShown=false;seenLogs=-1;syncControls();updateUI(true);toast('进度已恢复，点击继续航行')}catch{toast('存档无法读取，请重新开始任务')}}
$('#start').onclick=()=>sim.status==='ready'?start():sim.status==='paused'?togglePause():sim.status==='playing'?togglePause():showMissions();$('#resume').onclick=()=>togglePause();$('#ping').onclick=()=>perform('ping');$('#fire').onclick=()=>perform('fire');$('#decoy').onclick=()=>perform('deployDecoy');$('#repair').onclick=()=>perform('repair');$('#silent').onclick=()=>{sim.toggleSilent();syncControls();updateUI(true)};$('#save').onclick=save;$('#load').onclick=load;
function togglePause(){sim.togglePause();updateUI(true)}$('#pause').onclick=togglePause;$('#time-scale').onclick=()=>{sim.timeScale=sim.timeScale===1?2:sim.timeScale===2?4:1;updateUI(true)};
$('#speed').oninput=e=>sim.setSpeed(e.target.value);$('#heading').oninput=e=>sim.setHeading(e.target.value);$('#depth').oninput=e=>sim.setDepth(e.target.value);
$('#sound').onclick=()=>{soundOn=!soundOn;$('#sound').classList.toggle('active',soundOn);$('#sound').title=soundOn?'关闭声音':'开启声音';$('#sound').setAttribute('aria-label',$('#sound').title);toast(soundOn?'声呐与战斗音效已开启':'声音已关闭');tone(600,.3)};
$('#range').onclick=()=>{radarRange=radarRange===600?300:radarRange===300?1000:600;$('#range').textContent=radarRange/100+' km'};
$('[data-view="chase"]').onclick=()=>setView('chase');$('[data-view="sonar"]').onclick=()=>setView('sonar');$('[data-view="map"]').onclick=()=>setView('map');document.querySelectorAll('[data-camera]').forEach(b=>b.onclick=()=>{if(b.dataset.camera==='periscope'&&sim.player.depth>45){toast('潜望镜需要潜深 ≤ 45 米。请先上浮。');return}setView(b.dataset.camera);document.querySelectorAll('[data-camera]').forEach(c=>c.classList.toggle('active',c===b))});
function dialog(html){const d=$('#modal');if(!d.open&&sim.status==='playing'){sim.status='paused';d.dataset.resume='true'}else if(!d.open)d.dataset.resume='false';d.innerHTML=`<button class="modal-close icon-btn" aria-label="关闭">${icon('close')}</button>${html}`;d.querySelector('.modal-close').onclick=()=>d.close();if(!d.open)d.showModal();updateUI(true)}
$('#modal').addEventListener('close',()=>{if($('#modal').dataset.resume==='true'&&sim.status==='paused')sim.status='playing';updateUI(true)});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
function showMissions(){dialog(`<span class="overline">MISSION SELECT</span><h2>选择下一次出航</h2><p class="modal-intro">每片海域，都有不同的生存法则。</p><div class="mission-options">${MISSIONS.map((m,i)=>`<button class="mission-option ${m.id===sim.mission.id?'selected':''}" data-mission="${m.id}"><span class="mission-number">0${i+1}</span><span><small>${m.tag} · ${m.difficulty}</small><h3>${m.name}</h3><p>${m.desc}</p><b>${m.minutes} 分钟 · ${m.goal}</b></span>${icon('chevron')}</button>`).join('')}</div><p class="modal-foot">选择任务将开始新的航行。当前进度可通过右下角按钮保存。</p>`);document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{sim=new Simulation(b.dataset.mission);resultShown=false;seenLogs=-1;$('#modal').dataset.resume='false';$('#modal').close();syncControls();updateUI(true)})}
$('#missions').onclick=showMissions;
$('#help').onclick=()=>dialog(`<span class="overline">CAPTAIN'S HANDBOOK</span><h2>让海洋替你隐藏</h2><div class="help-grid"><div><b>01 / 监听与识别</b><p>低速航行有利于被动监听。点击接触选择目标；解算达到 62% 即可发射。主动声呐瞬间提高解算，同时增加暴露。</p></div><div><b>02 / 隐蔽与规避</b><p>静默模式限制 5 节。180 米温跃层会削弱跨层声波。被锁定后释放诱饵、转向并改变深度。超过 320 米会持续损伤艇体。</p></div><div><b>03 / 武器与生存</b><p>补给舰、护卫舰和潜艇 1 发击沉，驱逐舰需要 2 发。鱼雷具有制导能力。浅于 45 米恢复氧气与电力，但更容易被发现。</p></div><div><b>04 / 完成任务</b><p>无声猎手需要击沉补给舰后驶入绿色撤离区。海图点击任意位置可设置航向。任务支持暂停、时间加速和本机存档。</p></div></div><div class="key-grid"><span><kbd>W / S</kbd>加速 / 减速</span><span><kbd>A / D</kbd>左转 / 右转</span><span><kbd>Q / E</kbd>上浮 / 下潜</span><span><kbd>Space</kbd>主动声呐</span><span><kbd>F</kbd>发射鱼雷</span><span><kbd>G</kbd>释放诱饵</span><span><kbd>C</kbd>静默航行</span><span><kbd>P</kbd>战术暂停</span><span><kbd>M</kbd>战术海图</span><span><kbd>1 / 2 / 3</kbd>选择接触</span></div>`);
$('#logs').onclick=()=>{dialog(`<span class="overline">PATROL LOG</span><h2>航行记录</h2><div class="full-log">${sim.logs.map(l=>`<div class="log-entry ${l.kind}"><time>${clock(l.time)}</time><p>${l.text}</p></div>`).join('')}</div>`)};
document.addEventListener('keydown',e=>{if($('#modal').open||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;const key=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(key))e.preventDefault();if(e.repeat&&[' ','f','g','c','p','m','enter'].includes(key))return;if(key==='enter'&&sim.status==='ready'){e.preventDefault();start();}if(key==='w'||key==='arrowup')sim.setSpeed(sim.player.desiredSpeed+1);if(key==='s'||key==='arrowdown')sim.setSpeed(sim.player.desiredSpeed-1);if(key==='a'||key==='arrowleft')sim.setHeading(sim.player.desiredHeading-5);if(key==='d'||key==='arrowright')sim.setHeading(sim.player.desiredHeading+5);if(key==='q')sim.setDepth(sim.player.desiredDepth-10);if(key==='e')sim.setDepth(sim.player.desiredDepth+10);if(key===' ')perform('ping');if(key==='f')perform('fire');if(key==='g')perform('deployDecoy');if(key==='c')sim.toggleSilent();if(key==='p')togglePause();if(key==='m')setView(view==='map'?'chase':'map');if(['1','2','3'].includes(key)){const es=sim.enemies.filter(e=>e.alive&&e.known);if(es[+key-1])sim.select(es[+key-1].id)}syncControls();updateUI(true)});
function progress(id,n){$(id).style.width=clamp(n,0,100)+'%'}
function updateUI(force=false){const p=sim.player;if(view==='periscope'&&p.depth>45){setView('chase');toast('已离开潜望镜深度，潜望镜自动收回')}$('#mission-name').textContent=sim.mission.name;$('#operation-number').textContent='OPERATION 0'+(MISSIONS.indexOf(sim.mission)+1);$('#sector').textContent=sim.mission.sector;$('#mission-desc').textContent=sim.mission.desc;$('#remaining').textContent=clock(Math.max(0,sim.mission.minutes*60-sim.time));progress('#mission-progress',100-sim.time/(sim.mission.minutes*60)*100);
 const goals=sim.mission.id==='silent'?[['识别并击沉敌方补给舰',sim.targetSunk>=1],['抵达西南撤离区',sim.status==='won']]:sim.mission.id==='hunter'?[[`击沉攻击潜艇 (${sim.targetSunk}/2)`,sim.targetSunk>=2],['保护本艇，存活到任务结束',sim.status==='won']]:[[`通过航路点 (${sim.waypoint}/3)`,sim.waypoint>=3],['敌方锁定保持低于 85%',sim.status==='won']];$('#objectives').innerHTML=goals.map((g,i)=>`<div class="objective ${g[1]?'done':''}"><span>${g[1]?icon('check'):String(i+1).padStart(2,'0')}</span><p>${g[0]}</p></div>`).join('');
 $('#start').innerHTML=`${icon(sim.status==='playing'?'pause':'play')} ${sim.status==='ready'?'启动巡航':sim.status==='playing'?'暂停航行':sim.status==='paused'?'继续航行':'重新出航'} <kbd>${sim.status==='ready'?'Enter':'P'}</kbd>`;$('#load').hidden=sim.status!=='ready';$('#pause-overlay').hidden=sim.status!=='paused'||$('#modal').open;$('#game-state').textContent={ready:'待命',playing:'航行中',paused:'已暂停',won:'任务完成',lost:'任务结束'}[sim.status];$('#game-time').textContent='T+ '+clock(sim.time);$('#time-scale').textContent=sim.timeScale+'×';
 $('#speed-value').textContent=p.speed.toFixed(1);$('#speed-order').textContent='指令 '+p.desiredSpeed;$('#heading-value').textContent=String(Math.round(p.heading)%360).padStart(3,'0');$('#heading-order').textContent='指令 '+String(Math.round(p.desiredHeading)).padStart(3,'0')+'°';$('#depth-value').textContent=Math.round(p.depth);$('#depth-order').textContent='指令 '+p.desiredDepth;$('#ruler-depth').textContent=Math.round(p.depth);
 $('#noise-value').textContent=Math.round(p.noise);$('#noise-meter').innerHTML=Array.from({length:25},(_,i)=>`<i class="${i<p.noise/4?'lit':''}" style="--meter-color:${i<13?'#79d4af':i<19?'#d8be76':'#ea816b'}"></i>`).join('');$('#exposure-value').textContent=Math.round(p.exposure)+'%';progress('#exposure-meter',p.exposure);$('#exposure-meter').style.background=p.exposure>60?'var(--red)':p.exposure>30?'var(--amber)':'var(--mint)';$('#stealth-label').textContent=p.exposure>75?'遭到攻击':p.exposure>55?'敌方搜索':p.exposure>25?'警戒':'隐蔽';$('#stealth-label').style.color=p.exposure>60?'var(--red)':p.exposure>25?'var(--amber)':'var(--mint)';$('#thermal-info').innerHTML=icon('depth')+(p.depth>180?'温跃层掩护生效 · 跨层侦测减弱':'下潜至 180 m 以下可利用温跃层隐蔽');$('#thermal-info').classList.toggle('protected',p.depth>180);$('#depth-status').textContent=p.depth>180?'温跃层下方 · 隐蔽增强':'温跃层上方';
 const enemies=sim.enemies.filter(e=>e.known&&e.alive);$('#contact-count').textContent=String(enemies.length).padStart(2,'0');const contactsHTML=enemies.map(e=>`<button class="contact ${e.id===sim.selected?'selected':''}" data-contact="${e.id}"><span class="contact-icon ${e.confidence>.62?'confirmed':''}">${icon(e.type==='sub'?'sub':'target')}</span><span class="contact-text"><b>${e.id}<small>${sim.time-(e.lastContact?.time||0)>10?'失联接触':e.confidence>.62?({cargo:'补给舰',destroyer:'驱逐舰',frigate:'护卫舰',sub:'攻击潜艇'}[e.type]):'未知接触'}</small></b><span>方位 ${String(Math.round(angleTo(p,observed(e)))).padStart(3,'0')}° · ${e.confidence>.4?(distance(p,observed(e))/100).toFixed(1)+' km':'距离未知'}</span></span><span class="confidence">${Math.round(e.confidence*100)}<small>%</small></span></button>`).join('')||'<div class="empty-contacts">保持低速，搜索声学信号</div>';if($('#contacts').innerHTML!==contactsHTML){$('#contacts').innerHTML=contactsHTML;document.querySelectorAll('[data-contact]').forEach(b=>b.onclick=()=>{sim.select(b.dataset.contact);tone(450,.09);updateUI(true)})}
 const target=sim.enemies.find(e=>e.id===sim.selected&&e.alive);$('#target-info').innerHTML=target?`<span class="target-id">${target.id}</span><span><b>${target.confidence>.62?target.name:'未知声学接触'}</b><small>方位 ${Math.round(angleTo(p,observed(target)))}° · ${target.confidence>.4?(distance(p,observed(target))/100).toFixed(2)+' km':'距离未知'}</small></span>`:'选择声呐接触以建立射击解算';$('#solution-value').textContent=target?Math.round(target.confidence*100)+'%':'—';progress('#solution-meter',target?target.confidence*100:0);$('#ammo-count').textContent=String(p.torpedoes).padStart(2,'0')+' 枚';$('#fire-label').textContent=sim.fireCooldown>0?`装填中 ${Math.ceil(sim.fireCooldown)}s`:'发射鱼雷';$('#fire').classList.toggle('available',!!target&&target.confidence>=.62&&sim.fireCooldown<=0&&sim.status==='playing'&&p.torpedoes>0);$('#decoy-count').textContent=p.decoys;$('#decoy-label').textContent=sim.decoyCooldown>0?`准备中 ${Math.ceil(sim.decoyCooldown)}s`:'释放声学诱饵';$('#ping-label').textContent=sim.pingCooldown>0?`脉冲充能 ${Math.ceil(sim.pingCooldown)}s`:'主动声呐脉冲';$('#ping').classList.toggle('cooling',sim.pingCooldown>0);
 $('#hull').textContent=Math.max(0,Math.round(p.hull))+'%';$('#hull').style.color=p.hull<40?'var(--red)':'var(--mint)';progress('#hull-bar',p.hull);$('#battery').textContent=Math.round(p.battery)+'%';$('#oxygen').textContent=Math.round(p.oxygen)+'%';const alert=sim.torpedoes.some(t=>t.hostile)?'⚠ 来袭鱼雷 · 释放诱饵并改变航向':p.depth>320?'⚠ 超过安全潜深 · 艇体承压':p.exposure>65?'⚠ 敌方正在搜索本艇位置':'';$('#viewport-alert').textContent=alert;$('#viewport-alert').classList.toggle('show',!!alert);
 $('#compass-ribbon').innerHTML=Array.from({length:7},(_,i)=>{const n=(Math.round(p.heading/15)*15+(i-3)*15+360)%360;return `<span class="${i===3?'center':''}">${({0:'N',90:'E',180:'S',270:'W'}[n])||String(n).padStart(3,'0')}<i></i></span>`}).join('');
 const logSig=sim.logs.map(l=>l.text).join('');if(seenLogs!==logSig){seenLogs=logSig;$('#log-list').innerHTML=sim.logs.slice(0,3).map(l=>`<div class="log-entry ${l.kind}"><time>${clock(l.time)}</time><p>${l.text}</p></div>`).join('')}
 if((sim.status==='won'||sim.status==='lost')&&!resultShown){resultShown=true;showResult()}
}
function showResult(){const r=sim.result;try{const prev=+(localStorage.getItem('abyss-best')||0);if(r.score>prev)localStorage.setItem('abyss-best',r.score)}catch{}dialog(`<div class="result-icon ${r.won?'':'failed'}">${icon(r.won?'shield':'sub')}</div><span class="overline">${r.won?'MISSION ACCOMPLISHED':'PATROL ENDED'}</span><h2>${r.won?'静默归航':'深海仍在等待'}</h2><p class="modal-intro">${r.reason}</p><div class="result-stats"><div><strong>${r.score}</strong><span>战术得分</span></div><div><strong>${sim.sunk}</strong><span>击沉目标</span></div><div><strong>${clock(sim.time)}</strong><span>作战时间</span></div></div><p class="rank">${r.rank}</p><div class="result-actions"><button id="retry" class="primary-btn">再次挑战</button><button id="next-mission" class="secondary-btn">选择任务</button></div>`);$('#retry').onclick=()=>{sim=new Simulation(sim.mission.id);resultShown=false;seenLogs=-1;$('#modal').dataset.resume='false';$('#modal').close();syncControls();updateUI(true)};$('#next-mission').onclick=showMissions}
let radarPoints=[],mapPoints=[];
function drawRadar(canvas,big=false){const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;const dpr=Math.min(devicePixelRatio,2);if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=rect.width*dpr;canvas.height=rect.height*dpr}const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);const w=rect.width,h=rect.height,cx=w/2,cy=h/2,r=Math.min(w,h)*.43;const range=big?radarRange*1.2:radarRange;const scale=r/range;c.clearRect(0,0,w,h);c.fillStyle=big?'#091b1d':'#0b1e1d';c.fillRect(0,0,w,h);
 c.lineWidth=1;c.strokeStyle='#24443c';for(let i=1;i<=4;i++){c.beginPath();c.arc(cx,cy,r*i/4,0,Math.PI*2);c.stroke()}c.strokeStyle='#1a3832';for(let i=0;i<12;i++){let a=i*Math.PI/6;c.beginPath();c.moveTo(cx,cy);c.lineTo(cx+Math.sin(a)*r,cy-Math.cos(a)*r);c.stroke()}if(big){c.font='11px monospace';c.fillStyle='#4e766c';for(let i=1;i<=4;i++)c.fillText((range/100*i/4).toFixed(1)+' km',cx+7,cy-r*i/4+13);c.strokeStyle='#16302e';for(let x=0;x<w;x+=40){c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke()}for(let y=0;y<h;y+=40){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke()}}
 const a=displayTime*.3;c.save();c.beginPath();c.arc(cx,cy,r,0,Math.PI*2);c.clip();const grad=c.createConicGradient(a,cx,cy);grad.addColorStop(0,'#72e9b700');grad.addColorStop(.85,'#72e9b700');grad.addColorStop(1,'#72e9b724');c.fillStyle=grad;c.fillRect(cx-r,cy-r,r*2,r*2);c.strokeStyle='#81d9ad55';c.beginPath();c.moveTo(cx,cy);c.lineTo(cx+Math.cos(a)*r,cy+Math.sin(a)*r);c.stroke();c.restore();
 const p=sim.player;const project=o=>({x:cx+(o.x-p.x)*scale,y:cy+(o.z-p.z)*scale});let pts=[];const drawPoint=(o,col,sz=4)=>{const v=project(o);if(Math.hypot(v.x-cx,v.y-cy)>r)return null;c.fillStyle=col;c.beginPath();c.arc(v.x,v.y,sz,0,Math.PI*2);c.fill();return v};
 const goal=sim.mission.extract&&sim.targetSunk>=sim.mission.targets?sim.mission.extract:sim.mission.waypoints?.[sim.waypoint];if(goal){const v=project(goal);c.strokeStyle='#8be9bf';c.setLineDash([4,4]);c.beginPath();c.arc(v.x,v.y,48*scale,0,Math.PI*2);c.stroke();c.setLineDash([]);c.font='11px monospace';c.fillStyle='#8be9bf';c.fillText(sim.mission.extract?'撤离区':'航路点 '+(sim.waypoint+1),v.x+13,v.y-10);c.beginPath();c.moveTo(cx,cy);c.lineTo(v.x,v.y);c.stroke()}
 sim.enemies.filter(e=>e.alive&&e.known).forEach(e=>{const v=e.confidence>.4?project(observed(e)):{x:cx+Math.sin(angleTo(p,observed(e))*Math.PI/180)*r*.7,y:cy-Math.cos(angleTo(p,observed(e))*Math.PI/180)*r*.7};if(Math.hypot(v.x-cx,v.y-cy)>r)return;if(e.confidence<=.4){c.strokeStyle='#99baa433';c.setLineDash([2,5]);c.beginPath();c.moveTo(cx,cy);c.lineTo(v.x,v.y);c.stroke();c.setLineDash([])}const col=e.state==='攻击'?'#fb886b':e.confidence>.62?'#d5be7f':'#93b4a7';c.strokeStyle=col;c.fillStyle=col;c.lineWidth=e.id===sim.selected?2:1;c.save();c.translate(v.x,v.y);c.rotate(Math.PI/4);c.strokeRect(-4,-4,8,8);if(e.confidence>.62)c.fillRect(-2,-2,4,4);c.restore();if(e.id===sim.selected){c.beginPath();c.arc(v.x,v.y,12,0,Math.PI*2);c.stroke()}c.font=big?'12px monospace':'10px monospace';c.fillText(e.id,v.x+11,v.y-7);if(big)c.fillText(e.confidence>.4?(distance(p,observed(e))/100).toFixed(1)+'km':Math.round(angleTo(p,observed(e)))+'°',v.x+11,v.y+9);pts.push({id:e.id,...v})});
 for(const t of sim.torpedoes){const v=drawPoint(t,t.hostile?'#ff765e':'#d8ffd9',3);if(v){c.strokeStyle=t.hostile?'#ff765e88':'#b9e4c388';c.beginPath();c.moveTo(v.x,v.y);c.lineTo(v.x-Math.sin(t.heading*Math.PI/180)*12,v.y+Math.cos(t.heading*Math.PI/180)*12);c.stroke()}}for(const d of sim.decoys)drawPoint(d,'#7cb8f3',4);
 for(const pulse of sim.pulses){const v=project(pulse);c.strokeStyle=`rgba(129,240,184,${pulse.life*.17})`;c.beginPath();c.arc(v.x,v.y,pulse.r*scale,0,Math.PI*2);c.stroke()}
 c.save();c.translate(cx,cy);c.rotate(p.heading*Math.PI/180);c.fillStyle='#94efc6';c.beginPath();c.moveTo(0,-9);c.lineTo(-5,6);c.lineTo(0,3);c.lineTo(5,6);c.closePath();c.fill();c.strokeStyle='#a2eed955';c.setLineDash([3,4]);c.beginPath();c.moveTo(0,-12);c.lineTo(0,-r);c.stroke();c.restore();c.setLineDash([]);if(big){mapPoints=pts;c.fillStyle='#628f81';c.font='12px monospace';c.fillText('N',cx-4,cy-r-14);c.fillText('范围 '+(range/100).toFixed(1)+' km · 北向上',22,h-45);if(view==='sonar'){c.fillStyle='#77cead';c.fillText('PASSIVE ARRAY / 宽带监听',25,80)}}else radarPoints=pts;
}
function radarClick(event,big){const canvas=big?$('#tactical'):$('#radar');const r=canvas.getBoundingClientRect(),x=event.clientX-r.left,y=event.clientY-r.top;const point=(big?mapPoints:radarPoints).find(p=>Math.hypot(x-p.x,y-p.y)<22);if(point){sim.select(point.id);updateUI(true)}else if(big&&view==='map'){const bearing=(Math.atan2(x-r.width/2,r.height/2-y)*180/Math.PI+360)%360;sim.setHeading(bearing);syncControls();toast(`航向设为 ${Math.round(bearing)}°`)}}
$('#radar').onclick=e=>radarClick(e,false);$('#tactical').onclick=e=>radarClick(e,true);
try{scene=new OceanScene($('#ocean'))}catch(e){$('#ocean').innerHTML='<div class="webgl-error">三维画面初始化失败，请切换「战术海图」继续作战。</div>';console.error(e)}
let last=performance.now(),uiClock=0;function loop(now){const dt=Math.min(.05,(now-last)/1000);last=now;displayTime+=dt;sim.step(dt);scene?.update(sim,dt);drawRadar($('#radar'));if(view==='map'||view==='sonar')drawRadar($('#tactical'),true);uiClock+=dt;if(uiClock>.2){updateUI();uiClock=0}while(sim.events.length)eventSound(sim.events.shift());requestAnimationFrame(loop)}
syncControls();updateUI(true);requestAnimationFrame(loop);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&sim.status==='playing'){sim.status='paused';updateUI(true)}});
const modelContext=document.modelContext;
if(modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tool={name:'read_patrol_status',title:'读取潜艇战况',description:'Read visible submarine status, mission progress, and known sonar contacts without changing the game.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:input=>{if(input&&Object.keys(input).length)throw Error('No parameters expected');return {mission:sim.mission.name,status:sim.status,elapsed:Math.floor(sim.time),player:sim.player,contacts:sim.enemies.filter(e=>e.known&&e.alive).map(e=>({id:e.id,confidence:e.confidence,bearing:Math.round(angleTo(sim.player,observed(e))),range:e.confidence>.4?Math.round(distance(sim.player,observed(e))*10):null})),objectives:{sunk:sim.targetSunk,waypoints:sim.waypoint}}}};try{Promise.resolve(modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}
